                <div className="flex items-center gap-3">
                  <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-chart-2/10">
                    <SiWhatsapp className="h-5 w-5 text-chart-2" />
                  </div>
                  <CardTitle className="text-lg">WhatsApp</CardTitle>
                </div>
                <CardDescription>
                  Quick responses via WhatsApp
                </CardDescription>
              </CardHeader>
              <CardContent>
                <Button 
                  asChild 
                  className="w-full min-h-10 bg-chart-2 hover:bg-chart-2 border-chart-2"
                  data-testid="button-whatsapp"
                >
                  <a 
                    href={whatsappUrl} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="flex items-center justify-center gap-2"
                  >
                    <MessageCircle className="h-4 w-4" />
                    Chat on WhatsApp
                  </a>
                </Button>
              </CardContent>
            </Card>

            {/* Address Card */}
            <Card>
              <CardHeader className="gap-2 space-y-0">
                <div className="flex items-center gap-3">
                  <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
                    <MapPin className="h-5 w-5 text-primary" />
                  </div>
                  <CardTitle className="text-lg">Address</CardTitle>
                </div>
                <CardDescription>
                  Our office location
                </CardDescription>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-foreground" data-testid="text-address">
                  Dhaka 1212<br />
                  Bangladesh
                </p>
              </CardContent>
            </Card>

            {/* Email Card */}
            <Card>
              <CardHeader className="gap-2 space-y-0">
                <div className="flex items-center gap-3">
                  <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-chart-3/10">
                    <Mail className="h-5 w-5 text-chart-3" />
                  </div>
                  <CardTitle className="text-lg">Email</CardTitle>
                </div>
                <CardDescription>
                  Send us an email
                </CardDescription>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-foreground break-all" data-testid="text-email">
                  contact@atozai.com
                </p>
              </CardContent>
            </Card>
          </div>

          {/* Contact Form */}
          <div className="lg:col-span-2">
            <Card>
              <CardHeader>
                <CardTitle className="text-2xl">Send Us a Message</CardTitle>
                <CardDescription>
                  Fill out the form below and we'll get back to you shortly.
                </CardDescription>
              </CardHeader>
              <CardContent>
                {isSubmitted ? (
                  <div className="py-12 text-center space-y-4">
                    <div className="flex justify-center">
                      <div className="flex h-16 w-16 items-center justify-center rounded-full bg-chart-2/10">
                        <Send className="h-8 w-8 text-chart-2" />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <h3 className="text-xl font-semibold">Message Sent!</h3>
                      <p className="text-muted-foreground">
                        Thank you for reaching out. We'll respond to your message as soon as possible.
                      </p>
                    </div>
                    <Button
                      onClick={() => setIsSubmitted(false)}
                      variant="outline"
                      data-testid="button-send-another"
                    >
                      Send Another Message
                    </Button>
                  </div>
                ) : (
                  <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                      <FormField
                        control={form.control}
                        name="name"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Name</FormLabel>
                            <FormControl>
                              <Input
                                placeholder="Your name"
                                {...field}
                                data-testid="input-name"
                                className="min-h-10"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="email"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Email</FormLabel>
                            <FormControl>
                              <Input
                                type="email"
                                placeholder="your.email@example.com"
                                {...field}
                                data-testid="input-email"
                                className="min-h-10"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="message"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Message</FormLabel>
                            <FormControl>
                              <Textarea
                                placeholder="How can we help you?"
                                className="min-h-32 resize-none"
                                {...field}
                                data-testid="input-message"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <Button
                        type="submit"
                        className="w-full min-h-10"
                        disabled={contactMutation.isPending}
                        data-testid="button-submit"
                      >
                        {contactMutation.isPending ? (
                          "Sending..."
                        ) : (
                          <>
                            <Send className="mr-2 h-4 w-4" />
                            Send Message
                          </>
                        )}
                      </Button>
                    </form>
                  </Form>
                )}
              </CardContent>
            </Card>
          </div>
        </div>
      </section>

      {/* FAQ or Additional Info Section */}
      <section className="border-t bg-muted/30">
        <div className="container mx-auto px-4 md:px-6 lg:px-8 py-12">
          <div className="mx-auto max-w-4xl text-center space-y-4">
            <h2 className="font-serif text-3xl font-bold">
              Prefer WhatsApp?
            </h2>
            <p className="text-muted-foreground max-w-2xl mx-auto">
              For quick responses and instant support, reach out to us on WhatsApp. We're available to answer your questions and provide assistance.
            </p>
            <Button 
              asChild 
              size="lg"
              className="min-h-10 bg-chart-2 hover:bg-chart-2 border-chart-2"
              data-testid="button-whatsapp-cta"
            >
              <a 
                href={whatsappUrl} 
                target="_blank" 
                rel="noopener noreferrer"
                className="flex items-center gap-2"
              >
                <SiWhatsapp className="h-5 w-5" />
                Contact on WhatsApp
              </a>
            </Button>
          </div>
        </div>
      </section>
    </div>
  );
}
